// Resolve API base from runtime config when running in Electron; fallback to env or localhost
export function getApiBase() {
  try {
    if (typeof window !== "undefined" && window.desktop?.config?.apiBase) {
      return window.desktop.config.apiBase;
    }
  } catch {
    // ignore
  }
  const envBase = import.meta?.env?.VITE_API_BASE;
  return envBase || "http://localhost:3000";
}

export function isElectron() {
  return !!(
    typeof window !== "undefined" &&
    window.desktop &&
    window.desktop.isElectron
  );
}
